    // ---------- Finding the prop ----------

    private static Transform FindProp()
    {
        GameObject selected = Selection.activeGameObject;
        if (selected == null) return null;

        Transform walker = selected.transform;
        while (walker != null)
        {
            if (walker.name == PropName) return walker;
            walker = walker.parent;
        }

        VacuumAbsorber absorber = selected.GetComponentInParent<VacuumAbsorber>();
        Transform searchRoot = absorber != null ? absorber.transform : selected.transform;
        foreach (Transform candidate in searchRoot.GetComponentsInChildren<Transform>(true))
        {
            if (candidate.name == PropName) return candidate;
        }

        return null;
    }

    // ---------- Building blocks ----------

    private static GameObject Part(
        Transform prop, string partName, PrimitiveType type,
        Vector3 localPosition, Vector3 localEuler, Vector3 localScale, Material material)
    {
        GameObject part = GameObject.CreatePrimitive(type);
        part.name = partName;

        // Decorative only: no collider, so it never pushes the player or blocks anything.
        Object.DestroyImmediate(part.GetComponent<Collider>());

        Undo.RegisterCreatedObjectUndo(part, "Build junkyard look");
        part.transform.SetParent(prop, false);
        part.transform.localPosition = localPosition;
        part.transform.localRotation = Quaternion.Euler(localEuler);
        part.transform.localScale = localScale;
        part.GetComponent<MeshRenderer>().sharedMaterial = material;
        return part;
    }

    private static void Tube(Transform prop, string tubeName, Vector3 from, Vector3 to, float radius, Material material)
    {
        Vector3 direction = to - from;
        if (direction.sqrMagnitude < 0.000001f) return;

        // A Unity cylinder is 2 units tall and 1 unit wide, so the scale is half the length.
        // A little extra length makes consecutive segments overlap, so there are no gaps.
        GameObject tube = Part(prop, tubeName, PrimitiveType.Cylinder,
            (from + to) / 2f, Vector3.zero,
            new Vector3(radius * 2f, direction.magnitude / 2f * 1.08f, radius * 2f), material);
        tube.transform.localRotation = Quaternion.FromToRotation(Vector3.up, direction.normalized);
    }

    private static void Wire(Transform prop, string wireName, Vector3[] points, Material material)
    {
        for (int i = 0; i < points.Length - 1; i++)
        {
            Tube(prop, wireName + "_" + i, points[i], points[i + 1], 0.007f, material);
        }
    }

    // Smooth curve through the control points (Catmull-Rom).
    private static List<Vector3> SamplePath(Vector3[] controls, int samplesPerSpan)
    {
        List<Vector3> result = new List<Vector3>();
        int last = controls.Length - 1;

        for (int i = 0; i < last; i++)
        {
            Vector3 p0 = controls[Mathf.Max(i - 1, 0)];
            Vector3 p1 = controls[i];
            Vector3 p2 = controls[i + 1];
            Vector3 p3 = controls[Mathf.Min(i + 2, last)];

            for (int s = 0; s < samplesPerSpan; s++)
            {
                result.Add(CatmullRom(p0, p1, p2, p3, s / (float)samplesPerSpan));
            }
        }

        result.Add(controls[last]);
        return result;
    }

    private static Vector3 CatmullRom(Vector3 p0, Vector3 p1, Vector3 p2, Vector3 p3, float t)
    {
        float t2 = t * t;
        float t3 = t2 * t;
        return 0.5f * (2f * p1
            + (-p0 + p2) * t
            + (2f * p0 - 5f * p1 + 4f * p2 - p3) * t2
            + (-p0 + 3f * p1 - 3f * p2 + p3) * t3);
    }

    // ---------- Funnel mesh (a cone is not a Unity primitive) ----------

    private static Mesh GetFunnelMesh()
    {
        string path = MaterialFolder + "/SUCK_Funnel.asset";
        Mesh mesh = AssetDatabase.LoadAssetAtPath<Mesh>(path);
        bool isNew = mesh == null;
        if (isNew)
        {
            mesh = new Mesh();
            mesh.name = "SUCK_Funnel";
        }

        mesh.Clear();

        // Profile of the funnel: (radius, distance along Z), neck to mouth.
        Vector2[] profile =
        {
            new Vector2(0.045f, 0.0f),
            new Vector2(0.05f, 0.06f),
            new Vector2(0.1f, 0.14f),
            new Vector2(0.17f, 0.25f)
        };

        const int segments = 24;
        List<Vector3> vertices = new List<Vector3>();
        List<Vector2> uvs = new List<Vector2>();
        List<int> triangles = new List<int>();

        AddSurface(vertices, uvs, triangles, profile, segments, 0f, false);   // outside
        AddSurface(vertices, uvs, triangles, profile, segments, -0.012f, true); // inside (thickness)

        mesh.SetVertices(vertices);
        mesh.SetUVs(0, uvs);
        mesh.SetTriangles(triangles, 0);
        mesh.RecalculateNormals();
        mesh.RecalculateBounds();

        if (isNew)
        {
            AssetDatabase.CreateAsset(mesh, path);
        }
        else
        {
            EditorUtility.SetDirty(mesh);
        }

        return mesh;
    }

    private static void AddSurface(
        List<Vector3> vertices, List<Vector2> uvs, List<int> triangles,
        Vector2[] profile, int segments, float radiusOffset, bool flip)
    {
        int baseIndex = vertices.Count;

        for (int i = 0; i < profile.Length; i++)
        {
            float radius = Mathf.Max(profile[i].x + radiusOffset, 0.005f);
            float z = profile[i].y;

            for (int j = 0; j < segments; j++)
            {
                float angle = j / (float)segments * Mathf.PI * 2f;
                vertices.Add(new Vector3(Mathf.Cos(angle) * radius, Mathf.Sin(angle) * radius, z));
                uvs.Add(new Vector2(j / (float)segments, i / (float)(profile.Length - 1)));
            }
        }

        for (int i = 0; i < profile.Length - 1; i++)
        {
            for (int j = 0; j < segments; j++)
            {
                int nextJ = (j + 1) % segments;
                int a = baseIndex + i * segments + j;
                int b = baseIndex + i * segments + nextJ;
                int c = baseIndex + (i + 1) * segments + j;
                int d = baseIndex + (i + 1) * segments + nextJ;

                if (!flip)
                {
                    triangles.Add(a); triangles.Add(b); triangles.Add(c);
                    triangles.Add(b); triangles.Add(d); triangles.Add(c);
                }
                else
                {
                    triangles.Add(a); triangles.Add(c); triangles.Add(b);
                    triangles.Add(b); triangles.Add(c); triangles.Add(d);
                }
            }
        }
    }

    // ---------- Materials ----------

    private static Material Mat(string materialName, Color color, Texture2D texture, Vector2 tiling, float metallic, float smoothness)
    {
        string path = MaterialFolder + "/" + materialName + ".mat";
        Material material = AssetDatabase.LoadAssetAtPath<Material>(path);
        if (material == null)
        {
            Shader shader = Shader.Find("Universal Render Pipeline/Lit");
            if (shader == null) shader = Shader.Find("Standard");
            material = new Material(shader);
            AssetDatabase.CreateAsset(material, path);
        }

        if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", color);
        if (material.HasProperty("_Color")) material.SetColor("_Color", color);
        if (material.HasProperty("_Metallic")) material.SetFloat("_Metallic", metallic);
        if (material.HasProperty("_Smoothness")) material.SetFloat("_Smoothness", smoothness);
        if (material.HasProperty("_Glossiness")) material.SetFloat("_Glossiness", smoothness);

        if (texture != null)
        {
            if (material.HasProperty("_BaseMap"))
            {
                material.SetTexture("_BaseMap", texture);
                material.SetTextureScale("_BaseMap", tiling);
            }

            if (material.HasProperty("_MainTex"))
            {
                material.SetTexture("_MainTex", texture);
                material.SetTextureScale("_MainTex", tiling);
            }
        }

        EditorUtility.SetDirty(material);
        return material;
    }

    private static Material GlowMat(string materialName, Color color)
    {
        Material material = Mat(materialName, color, null, Vector2.one, 0f, 0.6f);
        material.EnableKeyword("_EMISSION");
        material.SetColor("_EmissionColor", color * 3f);
        EditorUtility.SetDirty(material);
        return material;
    }

    // ---------- Procedural textures ----------

    private static Texture2D MakeTexture(string textureName, int size, System.Func<int, int, int, Color> pixel)
    {
        string path = TextureFolder + "/" + textureName + ".png";

        Texture2D texture = new Texture2D(size, size, TextureFormat.RGBA32, false);
        for (int y = 0; y < size; y++)
        {
            for (int x = 0; x < size; x++)
            {
                texture.SetPixel(x, y, pixel(x, y, size));
            }
        }

        texture.Apply();
        File.WriteAllBytes(path, texture.EncodeToPNG());
        Object.DestroyImmediate(texture);

        AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
        return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
    }

    // Rusty grey metal with orange rust patches and groove lines.
    private static Color RustPixel(int x, int y, int size)
    {
        float patches = Mathf.PerlinNoise(x * 0.015f + 3f, y * 0.015f + 7f) * 0.7f
                      + Mathf.PerlinNoise(x * 0.08f, y * 0.08f) * 0.3f;
        float fine = Mathf.PerlinNoise(x * 0.5f, y * 0.5f);

        float grey = 0.55f + (fine - 0.5f) * 0.2f;
        Color metal = new Color(grey, grey, grey * 1.02f, 1f);
        Color rustColor = new Color(0.55f, 0.28f, 0.12f, 1f);

        Color color = Color.Lerp(metal, rustColor, Mathf.SmoothStep(0.45f, 0.7f, patches));

        if (y % 64 < 2)
        {
            color *= 0.6f;
        }

        color.a = 1f;
        return color;
    }

    // Red painted metal, chipped and rusty.
    private static Color RedPixel(int x, int y, int size)
    {
        float chips = Mathf.PerlinNoise(x * 0.05f + 11f, y * 0.05f + 5f);
        float fine = Mathf.PerlinNoise(x * 0.4f, y * 0.4f);

        Color paint = new Color(0.72f, 0.16f, 0.1f, 1f) * (0.9f + fine * 0.2f);
        Color rustColor = new Color(0.45f, 0.2f, 0.1f, 1f);

        Color color = Color.Lerp(paint, rustColor, Mathf.SmoothStep(0.55f, 0.8f, chips));
        color.a = 1f;
        return color;
    }

    // Lime green plastic with panel lines.
    private static Color GreenPixel(int x, int y, int size)
    {
        float variation = Mathf.PerlinNoise(x * 0.03f, y * 0.03f);
        Color color = new Color(0.55f, 0.82f, 0.3f, 1f) * (0.85f + variation * 0.3f);

        if (x % 64 < 2 || y % 64 < 2)
        {
            color *= 0.6f;
        }

        color.a = 1f;
        return color;
    }

    // Fan inside a square frame with screws.
    private static Color FanPixel(int x, int y, int size)
    {
        float u = (x / (float)size - 0.5f) * 2f;
        float v = (y / (float)size - 0.5f) * 2f;
        float r = Mathf.Sqrt(u * u + v * v);

        if (Mathf.Abs(u) > 0.82f && Mathf.Abs(v) > 0.82f) return new Color(0.75f, 0.75f, 0.78f, 1f); // screws
        if (Mathf.Abs(u) > 0.92f || Mathf.Abs(v) > 0.92f) return new Color(0.12f, 0.12f, 0.14f, 1f);  // frame
        if (r > 0.8f) return new Color(0.2f, 0.2f, 0.22f, 1f);
        if (r > 0.72f) return new Color(0.6f, 0.6f, 0.63f, 1f); // ring around the blades
        if (r < 0.15f) return new Color(0.5f, 0.5f, 0.52f, 1f); // hub

        float angle = Mathf.Atan2(v, u);
        float blade = Mathf.Sin(angle * 7f + r * 5f);
        float value = blade > 0.2f ? 0.75f : 0.25f;
        return new Color(value, value, value * 1.05f, 1f);
    }

    // Round pressure gauge with ticks and a red needle.
    private static Color GaugePixel(int x, int y, int size)
    {
        float u = (x / (float)size - 0.5f) * 2f;
        float v = (y / (float)size - 0.5f) * 2f;
        float r = Mathf.Sqrt(u * u + v * v);

        if (r > 0.9f) return new Color(0.1f, 0.1f, 0.1f, 1f);       // outer rim
        if (r > 0.8f) return new Color(0.7f, 0.7f, 0.72f, 1f);      // metal ring

        if (r < 0.08f) return Color.black;                          // needle hub

        float needleAngle = 0.6f;
        float distanceToNeedle = Mathf.Abs(u * Mathf.Sin(needleAngle) - v * Mathf.Cos(needleAngle));
        float along = u * Mathf.Cos(needleAngle) + v * Mathf.Sin(needleAngle);
        if (distanceToNeedle < 0.04f && along > 0f && r < 0.7f) return new Color(0.9f, 0.1f, 0.1f, 1f);

        float angle = Mathf.Atan2(v, u);
        if (r > 0.55f && r < 0.75f && Mathf.Sin(angle * 12f) > 0.9f) return Color.black; // ticks

        return new Color(0.95f, 0.95f, 0.9f, 1f);                   // face
    }

    // Silver duct tape with fibers.
    private static Color TapePixel(int x, int y, int size)
    {
        float fibers = Mathf.PerlinNoise(x * 1.2f, y * 0.05f);
        float value = 0.68f + (fibers - 0.5f) * 0.16f;
        return new Color(value, value * 1.02f, value * 1.05f, 1f);
    }

    // Brown leather.
    private static Color StrapPixel(int x, int y, int size)
    {
        float noise = Mathf.PerlinNoise(x * 0.2f, y * 0.2f);
        float value = 0.85f + (noise - 0.5f) * 0.3f;
        return new Color(0.45f * value, 0.3f * value, 0.15f * value, 1f);
    }

    // Horizontal ribs for the hose.
    private static Color RibPixel(int x, int y, int size)
    {
        float band = Mathf.Sin(y * Mathf.PI * 2f / 16f) * 0.5f + 0.5f;
        float value = 0.3f + 0.5f * band;
        return new Color(value, value, value, 1f);
    }

    // ---------- Folders ----------

    private static void EnsureFolders()
    {
        if (!AssetDatabase.IsValidFolder(MaterialFolder))
        {
            AssetDatabase.CreateFolder("Assets", "GameMaterials");
        }

        if (!AssetDatabase.IsValidFolder(TextureFolder))
        {
            AssetDatabase.CreateFolder(MaterialFolder, "Textures");
        }
    }
}
#endif
